-- --------------------------------------------------------------------------
-- BAGIAN 4: VERIFIKASI AKHIR HASIL RESTORE DI VPS (HARUS TEPAT SEMUA)
-- --------------------------------------------------------------------------
SELECT 
    r.id AS rombel_id,
    r.tingkat,
    r.nama_rombel,
    COUNT(s.id) AS total_siswa_aktif
FROM rombel r
LEFT JOIN siswa s ON s.rombel_id = r.id AND s.status_siswa = 'Aktif'
WHERE r.id IN (72, 74, 76, 70, 71)
GROUP BY r.id
ORDER BY r.tingkat ASC, r.nama_rombel ASC;
